<section class="container checkout-page"><h1>Cart</h1><div class="checkout-grid"><div class="cart-list"><?php foreach ($totals['items'] as $item): ?><article class="cart-item"><img src="<?= e($item['thumbnail']) ?>"><div><h3><?= e($item['name']) ?></h3><p><?= e($item['store_name'] ?? 'Marketplace Author') ?></p></div><strong><?= money($item['sale_price'] ?: $item['regular_price']) ?></strong></article><?php endforeach; ?><?php if (!$totals['items']): ?><p>Your cart is empty.</p><?php endif; ?></div><aside class="summary-card"><h2>Order Summary</h2><p><span>Subtotal</span><b><?= money($totals['subtotal']) ?></b></p><p><span>Discount</span><b>-<?= money($totals['discount']) ?></b></p><p class="total"><span>Total</span><b><?= money($totals['total']) ?></b></p><form class="coupon-form"><input id="couponCode" placeholder="Coupon code"><button type="button" data-apply-coupon>Apply</button></form><a class="green-btn" href="<?= e(app_url('checkout')) ?>">Checkout</a></aside></div></section>
